// Validate + normalize the incoming job, then base64-encode it so the
// Execute Command node can pass it to the Python wrapper without any shell
// quoting/injection risk (base64 alphabet is shell-safe).
const body = $json.body || {};

const inputs = body.inputs || (body.input ? [body.input] : []);
if (!Array.isArray(inputs) || inputs.length === 0) {
  throw new Error('Job must include a non-empty "inputs" array (or "input").');
}
if (!body.output_dir && !body.output) {
  throw new Error('Job must include "output_dir".');
}

const ALLOWED_ENH = ['upscale', 'noise', 'sharpen', 'lighting', 'color'];
const enh = body.enhancements || {};
for (const k of Object.keys(enh)) {
  if (!ALLOWED_ENH.includes(k)) {
    throw new Error(`Unknown enhancement '${k}'. Allowed: ${ALLOWED_ENH.join(', ')}`);
  }
}

// Whitelist the job shape we forward — drop anything unexpected.
const job = {
  inputs,
  output_dir: body.output_dir || body.output,
  enhancements: enh,
  format: body.format,
  quality: body.quality,
  overwrite: !!body.overwrite,
  recursive: !!body.recursive,
  override: !!body.override,
  skip_processing: !!body.skip_processing,
  show_settings: !!body.show_settings,
  timeout_s: body.timeout_s || 1800
};

const b64 = Buffer.from(JSON.stringify(job)).toString('base64');
return [{ json: { job, b64 } }];

// The wrapper prints one JSON object on stdout (plus INFO log lines on stderr).
// Parse the last non-empty stdout line as the result.
const raw = ($json.stdout || '').trim();
const lines = raw.split('\n').filter(Boolean);
let result;
try {
  result = JSON.parse(lines[lines.length - 1]);
} catch (e) {
  result = { ok: false, status: 'error', detail: 'Could not parse wrapper output', stdout: raw, stderr: $json.stderr };
}
return [{ json: result }];
